from pathlib import Path
import json
paths = [Path('docs/AGENTMAIL.md'), Path('docs/INTERAC-COMMANDES.md'), Path('docs/COMMERCIAL-FEEDBACK.md')]
terms = ('quote', 'devis', 'nonbinding', 'non-binding', 'administrative', 'original sender', 'acceptance')
report = {}
for path in paths:
    if not path.is_file():
        report[str(path)] = {'available': False}
        continue
    lines = path.read_text(encoding='utf-8').splitlines()
    hits = [{'line': index, 'text': line[:360]} for index, line in enumerate(lines, 1) if any(term in line.casefold() for term in terms)]
    report[str(path)] = {'available': True, 'matching_lines': len(hits), 'excerpts': hits[:16]}
output = Path('products/distribution/invoice-live-quote-rehearsal/documented-quote-route-excerpts.json')
output.parent.mkdir(parents=True, exist_ok=True)
output.write_text(json.dumps(report, ensure_ascii=False, indent=2) + '\n', encoding='utf-8')
print(output)
